from collections import defaultdict

def count_valid_triples(n: int, a_list: list) -> int:
    d = defaultdict(int)

    for a in a_list:
        d[a] += 1

    ans = 0
    for i in range(n):
        for j in range(n):
            product = a_list[i] * a_list[j]
            if product in d:
                ans += d[product]
    return ans

